94	/****************************************************************************
95	 * Cached GPIO pin state for fast bit-bang
96	 *
97	 * Instead of read-modify-write on every gpio_write() call, we cache the
98	 * CFG base value (with OUTPUT=0) and register address at setup time.
99	 * Setting a pin HIGH is then a single putreg32(base | OUTPUT_BIT).
100	 ****************************************************************************/
101	
102	typedef struct
103	{
104	  uintptr_t addr;   /* BK7258_GPIO_CFG(pin) address */
105	  uint32_t base_lo; /* CFG with OUTPUT bit cleared */
106	  uint32_t base_hi; /* CFG with OUTPUT bit set */
107	} gpio_cache_t;
108	
109	static gpio_cache_t g_cache_sclk;
110	static gpio_cache_t g_cache_mosi;
111	static gpio_cache_t g_cache_cs;
112	static gpio_cache_t g_cache_dc;
113	
114	/* Display geometry */
115	
116	#define LCD_WIDTH      160
117	#define LCD_HEIGHT     160
118	#define LCD_BPP        16  /* RGB565 */
119	
120	/* Test square size (Stage C) */
121	
122	#define SQ_SIZE        40
123	
124	/* SPI bit-bang delay: a few NOPs for timing margin. */
125	
126	#define spi_delay() \
127	  do { \
128	    __asm__ volatile("nop; nop; nop; nop;"); \
129	  } while (0)
