131	/****************************************************************************
132	 * Private Functions
133	 ****************************************************************************/
134	
135	/****************************************************************************
136	 * Name: gpio_set_output
137	 ****************************************************************************/
138	
139	static void gpio_set_output(int pin)
140	{
141	  uint32_t cfg = getreg32(BK7258_GPIO_CFG(pin));
142	
143	  cfg &= ~GPIO_CFG_SECOND_FUNC;  /* GPIO mode (bit6 = 0) */
144	  cfg &= ~GPIO_CFG_OUTPUT_EN;    /* output enable (bit3 active-low: 0 = on) */
145	  cfg &= ~GPIO_CFG_INPUT_EN;     /* input off (bit2: 0=off) */
146	  putreg32(cfg, BK7258_GPIO_CFG(pin));
147	}
148	
149	/****************************************************************************
150	 * Name: gpio_write
151	 ****************************************************************************/
152	
153	static void gpio_write(int pin, int val)
154	{
155	  uint32_t cfg = getreg32(BK7258_GPIO_CFG(pin));
156	
157	  if (val)
158	    {
159	      cfg |= GPIO_CFG_OUTPUT;
160	    }
161	  else
162	    {
163	      cfg &= ~GPIO_CFG_OUTPUT;
164	    }
165	
166	  putreg32(cfg, BK7258_GPIO_CFG(pin));
167	}
168	
169	/****************************************************************************
170	 * Name: gpio_set_output_cached
171	 *
172	 * Description:
173	 *   Configure pin as GPIO output and cache the CFG register values
174	 *   for fast putreg32-only writes (no getreg32 read needed later).
175	 *
176	 ****************************************************************************/
177	
178	static void gpio_set_output_cached(int pin, gpio_cache_t *c)
179	{
180	  uint32_t cfg;
181	
182	  c->addr = BK7258_GPIO_CFG(pin);
183	  cfg = getreg32(c->addr);
184	  cfg &= ~GPIO_CFG_SECOND_FUNC;
185	  cfg &= ~GPIO_CFG_OUTPUT_EN;
186	  cfg &= ~GPIO_CFG_INPUT_EN;
187	  cfg &= ~GPIO_CFG_OUTPUT;   /* output = 0 */
188	  putreg32(cfg, c->addr);
189	  c->base_lo = cfg;            /* OUTPUT=0 */
190	  c->base_hi = cfg | GPIO_CFG_OUTPUT; /* OUTPUT=1 */
191	}
192	
193	/****************************************************************************
194	 * Name: gpio_write_fast
195	 *
196	 * Description:
197	 *   Set pin via cached values — no read-modify-write, just a single
198	 *   putreg32.  ~2x faster than gpio_write().
199	 *
200	 ****************************************************************************/
201	
202	static inline void gpio_write_fast(const gpio_cache_t *c, int val)
203	{
204	  putreg32(val ? c->base_hi : c->base_lo, c->addr);
205	}
