207	/****************************************************************************
208	 * Name: lcd_set_pins / lcd_setup_pins
209	 ****************************************************************************/
210	
211	static void lcd_set_pins(const lcd_pins_t *pins)
212	{
213	  g_active_pins = pins;
214	}
215	
216	static void lcd_setup_pins(const lcd_pins_t *pins)
217	{
218	  lcd_set_pins(pins);
219	  gpio_set_output(pins->rst);
220	
221	  /* Cache SCLK/MOSI/CS/DC for fast bit-bang */
222	
223	  gpio_set_output_cached(pins->sclk, &g_cache_sclk);
224	  gpio_set_output_cached(pins->mosi, &g_cache_mosi);
225	  gpio_set_output_cached(pins->cs,   &g_cache_cs);
226	  gpio_set_output_cached(pins->dc,   &g_cache_dc);
227	
228	  /* Initial idle state: CS=HIGH, DC=HIGH, SCLK=LOW, MOSI=LOW */
229	
230	  gpio_write_fast(&g_cache_cs,   1);
231	  gpio_write_fast(&g_cache_dc,   1);
232	  gpio_write_fast(&g_cache_sclk, 0);
233	  gpio_write_fast(&g_cache_mosi, 0);
234	}
