236	/****************************************************************************
237	 * Name: spi_write_byte
238	 *
239	 * Description:
240	 *   Bit-bang one byte, MSB-first, SPI mode 0.
241	 *   Uses cached GPIO values (no getreg32 read) and no NOP delay.
242	 *   GC9D01 can handle fast SPI clock; add back one spi_delay() if
243	 *   display shows corruption.
244	 *
245	 ****************************************************************************/
246	
247	static void spi_write_byte(uint8_t byte)
248	{
249	  int bit;
250	
251	  for (bit = 7; bit >= 0; bit--)
252	    {
253	      gpio_write_fast(&g_cache_mosi, (byte >> bit) & 1);
254	      gpio_write_fast(&g_cache_sclk, 1);
255	      gpio_write_fast(&g_cache_sclk, 0);
256	    }
257	}
258	
259	/****************************************************************************
260	 * Name: lcd_send_cmd / lcd_send_data / lcd_send_cmd_data
261	 ****************************************************************************/
262	
263	static void lcd_send_cmd(uint8_t cmd)
264	{
265	  gpio_write_fast(&g_cache_dc, 0);
266	  gpio_write_fast(&g_cache_cs, 0);
267	  spi_write_byte(cmd);
268	  gpio_write_fast(&g_cache_cs, 1);
269	}
270	
271	static void lcd_send_data(const uint8_t *data, int len)
272	{
273	  int i;
274	
275	  gpio_write_fast(&g_cache_dc, 1);
276	  gpio_write_fast(&g_cache_cs, 0);
277	  for (i = 0; i < len; i++)
278	    {
279	      spi_write_byte(data[i]);
280	    }
281	
282	  gpio_write_fast(&g_cache_cs, 1);
283	}
284	
285	static void lcd_send_cmd_data(uint8_t cmd, const uint8_t *data, int len)
286	{
287	  lcd_send_cmd(cmd);
288	  if (len > 0)
289	    {
290	      lcd_send_data(data, len);
291	    }
292	}
