397	/****************************************************************************
398	 * Name: lcd_fill_rect
399	 *
400	 * Description:
401	 *   Fill a rectangle (x0,y0)-(x1,y1) with a single RGB565 color.
402	 *   Much smaller than full-screen fill — avoids millions of bit-bangs.
403	 *
404	 ****************************************************************************/
405	
406	static void lcd_fill_rect(uint16_t x0, uint16_t y0,
407	                          uint16_t x1, uint16_t y1,
408	                          uint16_t color)
409	{
410	  uint8_t ca[4];
411	  uint8_t ra[4];
412	  uint8_t hi = (color >> 8) & 0xff;
413	  uint8_t lo = color & 0xff;
414	  int npix = (int)(x1 - x0 + 1) * (int)(y1 - y0 + 1);
415	  int i;
416	
417	  /* CASET */
418	
419	  ca[0] = (x0 >> 8) & 0xff;
420	  ca[1] = x0 & 0xff;
421	  ca[2] = (x1 >> 8) & 0xff;
422	  ca[3] = x1 & 0xff;
423	  lcd_send_cmd_data(0x2a, ca, 4);
424	
425	  /* RASET */
426	
427	  ra[0] = (y0 >> 8) & 0xff;
428	  ra[1] = y0 & 0xff;
429	  ra[2] = (y1 >> 8) & 0xff;
430	  ra[3] = y1 & 0xff;
431	  lcd_send_cmd_data(0x2b, ra, 4);
432	
433	  /* RAMWR + pixel data */
434	
435	  lcd_send_cmd(0x2c);
436	  gpio_write_fast(&g_cache_dc, 1);
437	  gpio_write_fast(&g_cache_cs, 0);
438	  for (i = 0; i < npix; i++)
439	    {
440	      spi_write_byte(hi);
441	      spi_write_byte(lo);
442	    }
443	
444	  gpio_write_fast(&g_cache_cs, 1);
445	}
