447	/****************************************************************************
448	 * Name: sqrt_int — integer square root (Newton's method)
449	 ****************************************************************************/
450	
451	static int16_t sqrt_int(int32_t val)
452	{
453	  int32_t guess;
454	  int32_t next;
455	  int i;
456	
457	  if (val <= 0)
458	    {
459	      return 0;
460	    }
461	
462	  guess = val;
463	
464	  for (i = 0; i < 10; i++)
465	    {
466	      next = (guess + val / guess) / 2;
467	
468	      if (next >= guess)
469	        {
470	          break;
471	        }
472	
473	      guess = next;
474	    }
475	
476	  return (int16_t)guess;
477	}
