479	/****************************************************************************
480	 * Name: lcd_fill_circle
481	 *
482	 * Description:
483	 *   Fill a circle centred at (cx,cy) with radius r using scanline
484	 *   rendering.  Each scanline is a 1px-high lcd_fill_rect call.
485	 *
486	 ****************************************************************************/
487	
488	static void lcd_fill_circle(int16_t cx, int16_t cy, int16_t r,
489	                            uint16_t color)
490	{
491	  int16_t y;
492	  int16_t dx;
493	  int16_t x0;
494	  int16_t x1;
495	  int32_t r2 = (int32_t)r * r;
496	
497	  for (y = cy - r; y <= cy + r; y++)
498	    {
499	      int32_t dy  = (int32_t)(y - cy);
500	      int32_t rem = r2 - dy * dy;
501	
502	      if (rem < 0)
503	        {
504	          continue;
505	        }
506	
507	      dx = sqrt_int(rem);
508	      x0 = cx - dx;
509	      x1 = cx + dx;
510	
511	      if (x0 < 0)
512	        {
513	          x0 = 0;
514	        }
515	
516	      if (x1 >= LCD_WIDTH)
517	        {
518	          x1 = LCD_WIDTH - 1;
519	        }
520	
521	      if (y < 0 || y >= LCD_HEIGHT)
522	        {
523	          continue;
524	        }
525	
526	      lcd_fill_rect(x0, y, x1, y, color);
527	    }
528	}
