530	/****************************************************************************
531	 * Name: lcd_fill_round_rect
532	 *
533	 * Description:
534	 *   Fill a rounded rectangle centred at (cx,cy), width w, height h,
535	 *   corner radius r.  Built from one inner rect + four corner circles.
536	 *
537	 ****************************************************************************/
538	
539	static void lcd_fill_round_rect(int16_t cx, int16_t cy,
540	                                int16_t w, int16_t h,
541	                                int16_t r, uint16_t color)
542	{
543	  int16_t x0 = cx - w / 2;
544	  int16_t y0 = cy - h / 2;
545	  int16_t x1 = cx + w / 2;
546	  int16_t y1 = cy + h / 2;
547	
548	  /* Horizontal centre strip (full width, reduced height) */
549	
550	  lcd_fill_rect(x0, y0 + r, x1, y1 - r, color);
551	
552	  /* Vertical centre strip (reduced width, full height) */
553	
554	  lcd_fill_rect(x0 + r, y0, x1 - r, y1, color);
555	
556	  /* Four corner circles */
557	
558	  lcd_fill_circle(x0 + r, y0 + r, r, color);
559	  lcd_fill_circle(x1 - r, y0 + r, r, color);
560	  lcd_fill_circle(x0 + r, y1 - r, r, color);
561	  lcd_fill_circle(x1 - r, y1 - r, r, color);
562	}
