595	 *   Highlight:  white 0xFFFF, r=8, centre (80+gaze_dx-8, 80-10)
596	 *
597	 ****************************************************************************/
598	
599	#define EYE_CX        80
600	#define EYE_CY        80
601	#define EYE_IRIS_R    58
602	#define EYE_PUPIL_R   22
603	#define EYE_HIGHLIGHT_R 8
604	
