611	
612	  /* Black background */
613	
614	  lcd_fill_rect(0, 0, LCD_WIDTH - 1, LCD_HEIGHT - 1, 0x0000);
615	
616	  /* Cyan iris */
617	
618	  lcd_fill_circle(EYE_CX, EYE_CY, EYE_IRIS_R, 0x07ff);
619	
620	  /* Black pupil */
621	
622	  lcd_fill_circle(pcx, EYE_CY, EYE_PUPIL_R, 0x0000);
623	
624	  /* White highlight (upper-left of pupil) */
625	
626	  lcd_fill_circle(pcx - 8, EYE_CY - 10,
627	                  EYE_HIGHLIGHT_R, 0xffff);
628	}
