771	/****************************************************************************
772	 * Official-website-style eye: white bg + blue iris + black eyelids
773	 *
774	 * Color palette (RGB565):
775	 *   0xFFFF  white  (background)
776	 *   0x02DF  sky-blue (iris) — try 0x001F for deeper blue
777	 *   0x0000  black  (pupil, eyelids)
778	 *   0xFFFF  white  (highlight)
779	 ****************************************************************************/
780	
781	#define OEYE_BG        0xFFFF  /* white */
782	#define OEYE_IRIS      0x02DF  /* sky-blue */
783	#define OEYE_PUPIL     0x0000  /* black */
784	#define OEYE_HL        0xFFFF  /* white highlight */
785	#define OEYE_LID       0x0000  /* black eyelid */
786	
787	#define OEYE_IRIS_R    56     /* blue iris with visible white border */
788	#define OEYE_PUPIL_R   28     /* black pupil */
789	#define OEYE_HL1_R     10     /* primary highlight upper-left */
790	#define OEYE_HL1_X     68     /* primary highlight centre */
791	#define OEYE_HL1_Y     68
792	#define OEYE_HL2_R     4      /* secondary highlight lower-right */
793	#define OEYE_HL2_X     92     /* secondary highlight centre */
794	#define OEYE_HL2_Y     92
795	
796	/* Iris bounding box — the only region we redraw per frame.
797	 * iris at (80,80) r56 → x,y ∈ [24,136].
798	 */
799	
800	#define OEYE_BOX_L     24
801	#define OEYE_BOX_R     136
802	#define OEYE_BOX_T     24
803	#define OEYE_BOX_B     136
804	
805	/* Eyelid Y boundaries for each expression */
806	
807	#define OEYE_NEUTRAL_TOP  16   /* neutral: upper lid covers y 0..16 */
808	#define OEYE_NEUTRAL_BOT  143  /* neutral: lower lid covers y 143..159 */
809	#define OEYE_HALF_TOP     50   /* half: upper lid covers y 0..50 */
810	#define OEYE_HALF_BOT     110  /* half: lower lid covers y 110..159 */
811	#define OEYE_BLINK_TOP    70   /* blink: black arc top edge */
812	#define OEYE_BLINK_BOT    90   /* blink: black arc bottom edge */
813	#define OEYE_HAPPY_BOT    115  /* happy: lower lid pushed up */
814	
815	/****************************************************************************
816	 * Name: draw_oeye_bg
817	 *
818	 * Description:
819	 *   Full-screen white fill.  Call ONCE per panel before the
820	 *   expression loop.  Never called again during the loop.
821	 *
822	 ****************************************************************************/
823	
824	static void draw_oeye_bg(void)
825	{
826	  lcd_fill_rect(0, 0, LCD_WIDTH - 1, LCD_HEIGHT - 1, OEYE_BG);
827	}
828	
829	/****************************************************************************
830	 * Name: draw_oeye_content
831	 *
832	 * Description:
833	 *   Redraw only the iris bounding box: clear box to white, then
834	 *   draw blue iris + black pupil + two highlights.  This is the
835	 *   fast per-frame content update — no full-screen fill.
836	 *
837	 ****************************************************************************/
838	
839	static void draw_oeye_content(void)
840	{
841	  /* Clear iris box to white (erases previous pupil/highlight/lid) */
842	
843	  lcd_fill_rect(OEYE_BOX_L, OEYE_BOX_T, OEYE_BOX_R, OEYE_BOX_B,
844	                OEYE_BG);
845	
846	  /* Blue iris */
847	
848	  lcd_fill_circle(80, 80, OEYE_IRIS_R, OEYE_IRIS);
849	
850	  /* Black pupil */
851	
852	  lcd_fill_circle(80, 80, OEYE_PUPIL_R, OEYE_PUPIL);
853	
854	  /* Two white highlights */
855	
856	  lcd_fill_circle(OEYE_HL1_X, OEYE_HL1_Y, OEYE_HL1_R, OEYE_HL);
857	  lcd_fill_circle(OEYE_HL2_X, OEYE_HL2_Y, OEYE_HL2_R, OEYE_HL);
858	}
859	
860	/****************************************************************************
861	 * Name: eye_o_neutral
862	 *
863	 * Description:
864	 *   Neutral / fully open: redraw iris content + thin black eyelid
865	 *   strips top and bottom.  The strips are outside the iris box
866	 *   (y 0..16 and 143..159) so they overwrite the white bg there.
867	 *
868	 ****************************************************************************/
869	
870	static void eye_o_neutral(void)
871	{
872	  draw_oeye_content();
873	
874	  /* Upper eyelid: thin black strip at top */
875	
876	  lcd_fill_rect(0, 0, LCD_WIDTH - 1, OEYE_NEUTRAL_TOP, OEYE_LID);
877	
878	  /* Lower eyelid: thin black strip at bottom */
879	
880	  lcd_fill_rect(0, OEYE_NEUTRAL_BOT, LCD_WIDTH - 1, LCD_HEIGHT - 1,
881	                OEYE_LID);
882	}
883	
884	/****************************************************************************
885	 * Name: eye_o_half
886	 *
887	 * Description:
888	 *   Half-closed: redraw iris content + wider black eyelid strips.
889	 *   Upper lid extends into the iris box (y 0..50), lower lid
890	 *   extends into the iris box (y 110..159).
891	 *
892	 ****************************************************************************/
893	
894	static void eye_o_half(void)
895	{
896	  draw_oeye_content();
897	
898	  /* Upper eyelid: covers top portion of iris (extends into box) */
899	
900	  lcd_fill_rect(0, 0, LCD_WIDTH - 1, OEYE_HALF_TOP, OEYE_LID);
901	
902	  /* Lower eyelid: covers bottom portion (extends into box) */
903	
904	  lcd_fill_rect(0, OEYE_HALF_BOT, LCD_WIDTH - 1, LCD_HEIGHT - 1,
905	                OEYE_LID);
906	}
