908	/****************************************************************************
909	 * Name: eye_o_blink
910	 *
911	 * Description:
912	 *   Fully closed: clear iris box to white + draw thick black band
913	 *   y70..90.  Also restore any previous eyelid strips outside the
914	 *   box (top/bottom) back to white so only the black arc remains.
915	 *
916	 ****************************************************************************/
917	
918	static void eye_o_blink(void)
919	{
920	  /* Clear iris box to white */
921	
922	  lcd_fill_rect(OEYE_BOX_L, OEYE_BOX_T, OEYE_BOX_R, OEYE_BOX_B,
923	                OEYE_BG);
924	
925	  /* Restore top/bottom strips outside box to white
926	   * (removes leftover black eyelid from previous frame)
927	   */
928	
929	  lcd_fill_rect(0, 0, LCD_WIDTH - 1, OEYE_BOX_T - 1, OEYE_BG);
930	  lcd_fill_rect(0, OEYE_BOX_B + 1, LCD_WIDTH - 1, LCD_HEIGHT - 1,
931	                OEYE_BG);
932	
933	  /* Black arc: thick band across the middle of the iris box */
934	
935	  lcd_fill_rect(OEYE_BOX_L, OEYE_BLINK_TOP, OEYE_BOX_R, OEYE_BLINK_BOT,
936	                OEYE_LID);
937	}
938	
939	/****************************************************************************
940	 * Name: eye_o_happy
941	 *
942	 * Description:
943	 *   Happy: redraw iris content + thin top lid + lower lid pushed
944	 *   up to y=115 (smile arc).  Lower lid extends into the iris box.
945	 *
946	 ****************************************************************************/
947	
948	static void eye_o_happy(void)
949	{
950	  draw_oeye_content();
951	
952	  /* Upper eyelid: thin strip (same as neutral) */
953	
954	  lcd_fill_rect(0, 0, LCD_WIDTH - 1, OEYE_NEUTRAL_TOP, OEYE_LID);
955	
956	  /* Lower eyelid: push up to carve a smile arc */
957	
958	  lcd_fill_rect(0, OEYE_HAPPY_BOT, LCD_WIDTH - 1, LCD_HEIGHT - 1,
959	                OEYE_LID);
960	}
961	
962	/****************************************************************************
963	 * Smooth blink animation — incremental eyelid sweep
964	 *
965	 * Instead of jumping neutral → half → blink in 3 big frames, the eyelids
966	 * sweep in ~10-12 small steps.  Each step only draws a narrow black band
967	 * (closing) or redraws the revealed eye content (opening), so the per-step
968	 * pixel count is tiny — even bit-bang can do it smoothly.
969	 *
970	 *   Closing: top lid descends from OEYE_NEUTRAL_TOP → OEYE_BLINK_TOP,
971	 *            bottom lid ascends from OEYE_NEUTRAL_BOT → OEYE_BLINK_BOT.
972	 *   Opening: reverse.
973	 ****************************************************************************/
974	
975	#define OEYE_BLINK_STEPS  10  /* number of animation sub-frames */
976	
977	/****************************************************************************
978	 * Name: oeye_pixel_color
979	 *
980	 * Description:
981	 *   Return the RGB565 color for pixel (px, py) in the eye content.
982	 *   Checks highlight, pupil, iris, then falls back to background.
983	 *
984	 ****************************************************************************/
985	
986	static inline uint16_t oeye_pixel_color(int16_t px, int16_t py)
987	{
988	  int16_t ddx;
989	  int16_t ddy;
990	  int32_t d2;
991	
992	  /* Highlight 1 */
993	
994	  ddx = px - OEYE_HL1_X;
995	  ddy = py - OEYE_HL1_Y;
996	
997	  if ((int32_t)ddx * ddx + (int32_t)ddy * ddy <=
998	      (int32_t)OEYE_HL1_R * OEYE_HL1_R)
999	    {
1000	      return OEYE_HL;
1001	    }
1002	
1003	  /* Highlight 2 */
1004	
1005	  ddx = px - OEYE_HL2_X;
1006	  ddy = py - OEYE_HL2_Y;
1007	
1008	  if ((int32_t)ddx * ddx + (int32_t)ddy * ddy <=
1009	      (int32_t)OEYE_HL2_R * OEYE_HL2_R)
1010	    {
1011	      return OEYE_HL;
1012	    }
1013	
1014	  /* Pupil */
1015	
1016	  ddx = px - 80;
1017	  ddy = py - 80;
1018	  d2 = (int32_t)ddx * ddx + (int32_t)ddy * ddy;
1019	
1020	  if (d2 <= (int32_t)OEYE_PUPIL_R * OEYE_PUPIL_R)
1021	    {
1022	      return OEYE_PUPIL;
1023	    }
1024	
1025	  /* Iris */
1026	
1027	  if (d2 <= (int32_t)OEYE_IRIS_R * OEYE_IRIS_R)
1028	    {
1029	      return OEYE_IRIS;
1030	    }
1031	
1032	  return OEYE_BG;
1033	}
1034	
1035	/****************************************************************************
1036	 * Name: oeye_draw_row_band
1037	 *
1038	 * Description:
1039	 *   Draw eye content (iris/pupil/highlights/bg) for rows y0..y1,
1040	 *   clipped to the iris bounding box X range.  Uses CASET/RASET once
1041	 *   and streams pixels row by row — much faster than lcd_fill_circle
1042	 *   per row.
1043	 *
1044	 ****************************************************************************/
1045	
1046	static void oeye_draw_row_band(int16_t y0, int16_t y1)
1047	{
1048	  uint8_t ca[4];
1049	  uint8_t ra[4];
1050	  uint8_t cmd[2];
1051	  int16_t x;
1052	  int16_t y;
1053	  int16_t x0 = OEYE_BOX_L;
1054	  int16_t x1 = OEYE_BOX_R;
1055	
1056	  /* CASET + RASET for the band */
1057	
1058	  ca[0] = (x0 >> 8) & 0xff;
1059	  ca[1] = x0 & 0xff;
1060	  ca[2] = (x1 >> 8) & 0xff;
1061	  ca[3] = x1 & 0xff;
1062	  lcd_send_cmd_data(0x2a, ca, 4);
1063	
1064	  ra[0] = (y0 >> 8) & 0xff;
1065	  ra[1] = y0 & 0xff;
1066	  ra[2] = (y1 >> 8) & 0xff;
1067	  ra[3] = y1 & 0xff;
1068	  lcd_send_cmd_data(0x2b, ra, 4);
1069	
1070	  /* RAMWR — stream pixels row by row */
1071	
1072	  lcd_send_cmd(0x2c);
1073	  gpio_write_fast(&g_cache_dc, 1);
1074	  gpio_write_fast(&g_cache_cs, 0);
1075	
1076	  for (y = y0; y <= y1; y++)
1077	    {
1078	      for (x = x0; x <= x1; x++)
1079	        {
1080	          uint16_t c = oeye_pixel_color(x, y);
1081	
1082	          cmd[0] = (c >> 8) & 0xff;
1083	          cmd[1] = c & 0xff;
1084	          spi_write_byte(cmd[0]);
1085	          spi_write_byte(cmd[1]);
1086	        }
1087	    }
1088	
1089	  gpio_write_fast(&g_cache_cs, 1);
1090	}
1091	
1092	/****************************************************************************
1093	 * Name: eye_o_blink_anim
1094	 *
1095	 * Description:
1096	 *   Smooth eyelid animation: close → brief hold → open.
1097	 *   Each step draws only the narrow newly-occluded/revealed strip,
1098	 *   so the per-step pixel count is small (160×~6px for 10 steps).
1099	 *
1100	 ****************************************************************************/
1101	
1102	static void eye_o_blink_anim(void)
1103	{
1104	  int step;
1105	  int16_t top_prev;
1106	  int16_t top_cur;
1107	  int16_t bot_prev;
1108	  int16_t bot_cur;
1109	
1110	  /* --- Phase 1: close (top lid descends, bottom lid ascends) --- */
1111	
1112	  top_prev = OEYE_NEUTRAL_TOP;
1113	  bot_prev = OEYE_NEUTRAL_BOT;
1114	
1115	  for (step = 1; step <= OEYE_BLINK_STEPS; step++)
1116	    {
1117	      /* Interpolate lid positions */
1118	
1119	      top_cur = OEYE_NEUTRAL_TOP +
1120	                (int16_t)((int32_t)(OEYE_BLINK_TOP - OEYE_NEUTRAL_TOP) *
1121	                          step / OEYE_BLINK_STEPS);
1122	      bot_cur = OEYE_NEUTRAL_BOT +
1123	                (int16_t)((int32_t)(OEYE_BLINK_BOT - OEYE_NEUTRAL_BOT) *
1124	                          step / OEYE_BLINK_STEPS);
1125	
1126	      /* Draw newly covered rows as black (only the delta strip) */
1127	
1128	      if (top_cur > top_prev)
1129	        {
1130	          lcd_fill_rect(OEYE_BOX_L, top_prev + 1,
1131	                        OEYE_BOX_R, top_cur, OEYE_LID);
1132	        }
1133	
1134	      if (bot_cur < bot_prev)
1135	        {
1136	          lcd_fill_rect(OEYE_BOX_L, bot_cur,
1137	                        OEYE_BOX_R, bot_prev - 1, OEYE_LID);
1138	        }
1139	
1140	      top_prev = top_cur;
1141	      bot_prev = bot_cur;
1142	    }
1143	
1144	  /* --- Phase 2: brief hold at fully closed --- */
1145	
1146	  up_mdelay(60);
1147	
1148	  /* --- Phase 3: open (top lid ascends, bottom lid descends) --- */
1149	
1150	  for (step = OEYE_BLINK_STEPS - 1; step >= 0; step--)
1151	    {
1152	      top_cur = OEYE_NEUTRAL_TOP +
1153	                (int16_t)((int32_t)(OEYE_BLINK_TOP - OEYE_NEUTRAL_TOP) *
1154	                          step / OEYE_BLINK_STEPS);
1155	      bot_cur = OEYE_NEUTRAL_BOT +
1156	                (int16_t)((int32_t)(OEYE_BLINK_BOT - OEYE_NEUTRAL_BOT) *
1157	                          step / OEYE_BLINK_STEPS);
1158	
1159	      /* Redraw revealed rows with eye content (only the delta strip) */
1160	
1161	      if (top_cur < top_prev)
1162	        {
1163	          oeye_draw_row_band(top_cur + 1, top_prev);
1164	        }
1165	
1166	      if (bot_cur > bot_prev)
1167	        {
1168	          oeye_draw_row_band(bot_prev, bot_cur - 1);
1169	        }
1170	
1171	      top_prev = top_cur;
1172	      bot_prev = bot_cur;
1173	    }
1174	
1175	  /* Restore the thin neutral eyelid strips (outside iris box) */
1176	
1177	  lcd_fill_rect(0, 0, LCD_WIDTH - 1, OEYE_NEUTRAL_TOP, OEYE_LID);
1178	  lcd_fill_rect(0, OEYE_NEUTRAL_BOT, LCD_WIDTH - 1, LCD_HEIGHT - 1,
1179	                OEYE_LID);
1180	}
1181	
1182	/****************************************************************************
1183	 * Name: lcdtest_stages
1184	 *
1185	 * Description:
1186	 *   Staged LCD bring-up: A=backlight, B=init, C=40x40 red square.
1187	 *
1188	 ****************************************************************************/
1189	
1190	static int lcdtest_stages(void)
1191	{
1192	  /* --- Stage A: backlight --- */
1193	
1194	  syslog(LOG_INFO,
1195	         "[lcdtest] Stage A: backlight ON (P25 high)\n");
