1236	/****************************************************************************
1237	 * Name: lcdtest_scan
1238	 *
1239	 * Description:
1240	 *   Scan GPIO 0-47 for the LCD power enable pin.
1241	 *   Strategy: cumulative — pull each pin high and leave it high, so that
1242	 *   if multiple pins need to be high simultaneously the condition is met.
1243	 *   P25 (backlight) is held high throughout.  UART console pins (10, 11)
1244	 *   and LCD signal pins (2-5, 29) are skipped to keep the console and
1245	 *   SPI bus alive.
1246	 *
1247	 ****************************************************************************/
1248	
1249	static int lcdtest_scan(void)
1250	{
1251	  int pin;
1252	
1253	  /* Backlight on first */
1254	
1255	  gpio_set_output(LCD_PIN_BL);
1256	  gpio_write(LCD_PIN_BL, 1);
1257	
1258	  syslog(LOG_INFO,
1259	         "[scan] backlight P25 high, scanning GPIO 0-47 ...\n");
1260	
1261	  for (pin = 0; pin <= 47; pin++)
1262	    {
1263	      /* Skip UART0 console: RX=10, TX=11 */
1264	
1265	      if (pin == 10 || pin == 11)
1266	        {
1267	          syslog(LOG_INFO,
1268	                 "[scan] pin=%d skipped (UART0 console)\n", pin);
1269	          continue;
1270	        }
1271	
1272	      /* Skip LCD signal pins (both eyes + backlight) */
1273	
1274	      if (pin == g_lcd_left.sclk  || pin == g_lcd_left.cs  ||
1275	          pin == g_lcd_left.mosi  || pin == g_lcd_left.dc  ||
1276	          pin == g_lcd_left.rst   ||
1277	          pin == g_lcd_right.sclk || pin == g_lcd_right.cs ||
1278	          pin == g_lcd_right.mosi || pin == g_lcd_right.dc ||
1279	          pin == g_lcd_right.rst  ||
1280	          pin == LCD_PIN_BL)
1281	        {
1282	          syslog(LOG_INFO,
1283	                 "[scan] pin=%d skipped (LCD signal)\n", pin);
1284	          continue;
1285	        }
1286	
1287	      /* Skip SWD debug port: SWCLK=20, SWDIO=21 */
1288	
1289	      if (pin == 20 || pin == 21)
1290	        {
1291	          syslog(LOG_INFO,
1292	                 "[scan] pin=%d skipped (SWD debug)\n", pin);
1293	          continue;
1294	        }
1295	
1296	      gpio_set_output(pin);
1297	      gpio_write(pin, 1);
1298	      up_mdelay(800);
1299	
1300	      syslog(LOG_INFO, "[scan] pin=%d high\n", pin);
1301	    }
1302	
1303	  syslog(LOG_INFO,
1304	         "[scan] done - check screen for any change\n");
1305	
1306	  return OK;
1307	}
