1309	/****************************************************************************
1310	 * Name: lcdtest_pwr
1311	 *
1312	 * Description:
1313	 *   Full power-on sequence with configurable GPIO range for binary-search
1314	 *   identification of the LCD power enable pin.
1315	 *
1316	 *   Usage: lcdtest pwr [lo] [hi]
1317	 *     lo..hi  — decimal GPIO range to drive high (default 0..52)
1318	 *
1319	 *   Always skips: 2,3,4,5,25,29 (LCD)  10,11 (UART)  7,8 (motor)
1320	 *                 20,21 (SWD)  38,39 (LEDs)
1321	 *
1322	 ****************************************************************************/
1323	
1324	static int lcdtest_pwr(int lo, int hi)
1325	{
1326	  int pin;
1327	  int count = 0;
1328	  int off = 0;
1329	  char pinbuf[256];
1330	
1331	  /* Step 1: drive GPIO lo..hi high, skip reserved pins.
1332	   * Collect the actual pin list for the syslog dump.
1333	   */
1334	
1335	  syslog(LOG_INFO,
1336	         "[pwr] step1: GPIO %d-%d high (skip reserved)\n",
1337	         lo, hi);
1338	
1339	  for (pin = lo; pin <= hi; pin++)
1340	    {
1341	      /* LCD signals (both eyes) */
1342	
1343	      if (pin == 2 || pin == 3 || pin == 4 || pin == 5 ||
1344	          pin == 6 || pin == 7 || pin == 22 || pin == 23 ||
1345	          pin == 24 || pin == 25 || pin == 29)
1346	        {
1347	          continue;
1348	        }
1349	
1350	      /* UART0 console */
1351	
1352	      if (pin == 10 || pin == 11)
1353	        {
1354	          continue;
1355	        }
1356	
1357	      /* Vibration motor (P7 is right-eye DC, only skip P8) */
1358	
1359	      if (pin == 8)
1360	        {
1361	          continue;
1362	        }
1363	
1364	      /* Indicator LEDs */
1365	
1366	      if (pin == 38 || pin == 39)
1367	        {
1368	          continue;
1369	        }
1370	
1371	      /* SWD debug port: SWCLK=20, SWDIO=21 */
1372	
1373	      if (pin == 20 || pin == 21)
1374	        {
1375	          continue;
1376	        }
1377	
1378	      gpio_set_output(pin);
1379	      gpio_write(pin, 1);
1380	      count++;
1381	
1382	      if (off < (int)sizeof(pinbuf) - 8)
1383	        {
1384	          off += snprintf(pinbuf + off, sizeof(pinbuf) - off,
1385	                          " %d", pin);
1386	        }
1387	    }
1388	
1389	  pinbuf[off] = '\0';
1390	
1391	  /* Print which pins were actually driven high */
1392	
1393	  syslog(LOG_INFO,
1394	         "[pwr] driven high (%d pins):%s\n", count, pinbuf);
1395	
1396	  /* Step 2: wait for power rails to settle */
1397	
1398	  syslog(LOG_INFO, "[pwr] step2: wait 50 ms ...\n");
1399	  up_mdelay(50);
1400	
1401	  /* Step 3: backlight on */
1402	
1403	  syslog(LOG_INFO, "[pwr] step3: backlight P25 high\n");
1404	  gpio_set_output(LCD_PIN_BL);
1405	  gpio_write(LCD_PIN_BL, 1);
1406	
1407	  /* Step 4: setup left-eye SPI pins + hardware reset */
1408	
1409	  syslog(LOG_INFO,
1410	         "[pwr] step4: left SPI setup + RST low 15 ms then high\n");
1411	  lcd_setup_pins(&g_lcd_left);
1412	  gpio_write(g_active_pins->rst, 0);
1413	  up_mdelay(15);
1414	  gpio_write(g_active_pins->rst, 1);
1415	  up_mdelay(120);
1416	
1417	  /* Step 5: GC9D01 init sequence */
1418	
1419	  syslog(LOG_INFO, "[pwr] step5: GC9D01 init sequence\n");
1420	  lcd_init_sequence(true);
1421	
1422	  /* Step 6: clear screen to black */
1423	
1424	  syslog(LOG_INFO, "[pwr] step6: fill screen black\n");
1425	  lcd_fill_rect(0, 0, LCD_WIDTH - 1, LCD_HEIGHT - 1, 0x0000);
1426	
1427	  /* Step 7: draw 40x40 red square at (60,60) */
1428	
1429	  syslog(LOG_INFO,
1430	         "[pwr] step7: fill 40x40 red at (60,60)\n");
1431	  lcd_fill_rect(60, 60,
1432	                60 + SQ_SIZE - 1, 60 + SQ_SIZE - 1,
1433	                0xf800);
1434	
1435	  syslog(LOG_INFO,
1436	         "[pwr] done (%d pins driven) - "
1437	         "screen should show red on black\n",
1438	         count);
1439	  return OK;
1440	}
