1565	 ****************************************************************************/
1566	
1567	static int lcdtest_anim(void)
1568	{
1569	  int pin;
1570	  int count = 0;
1571	  int round;
1572	  int gaze = 0;
1573	
1574	  /* --- Power-on (same as go step1-3) --- */
1575	
1576	  syslog(LOG_INFO,
1577	         "[anim] step1: GPIO 0-52 high (skip reserved)\n");
1578	
1579	  for (pin = 0; pin <= 52; pin++)
1580	    {
1581	      if (pin == 2 || pin == 3 || pin == 4 || pin == 5 ||
1582	          pin == 6 || pin == 7 || pin == 22 || pin == 23 ||
1583	          pin == 24 || pin == 25 || pin == 29)
1584	        {
1585	          continue;
1586	        }
1587	
1588	      if (pin == 10 || pin == 11 || pin == 8 ||
1589	          pin == 20 || pin == 21 ||
1590	          pin == 38 || pin == 39)
1591	        {
1592	          continue;
1593	        }
1594	
1595	      gpio_set_output(pin);
1596	      gpio_write(pin, 1);
1597	      count++;
1598	    }
1599	
1600	  syslog(LOG_INFO, "[anim] step1 done: %d pins\n", count);
1601	
1602	  syslog(LOG_INFO, "[anim] step2: wait 500 ms\n");
1603	  up_mdelay(500);
1604	
1605	  syslog(LOG_INFO, "[anim] step3: backlight P25 high\n");
1606	  gpio_set_output(LCD_PIN_BL);
1607	  gpio_write(LCD_PIN_BL, 1);
1608	
1609	  /* --- Init left eye --- */
1610	
1611	  syslog(LOG_INFO, "[anim] init left eye\n");
1612	  lcd_setup_pins(&g_lcd_left);
1613	  gpio_write(g_active_pins->rst, 0);
1614	  up_mdelay(15);
1615	  gpio_write(g_active_pins->rst, 1);
1616	  up_mdelay(120);
1617	  lcd_init_sequence(false);
1618	  eye_draw_full(0);
1619	  lcd_display_on();
1620	
1621	  /* --- Init right eye --- */
1622	
1623	  syslog(LOG_INFO, "[anim] init right eye\n");
