1651	      syslog(LOG_INFO, "[anim] look centre\n");
1652	      lcd_set_pins(&g_lcd_left);
1653	      eye_move_pupil(gaze, 0);
1654	      lcd_set_pins(&g_lcd_right);
1655	      eye_move_pupil(gaze, 0);
