1833	/****************************************************************************
1834	 * Name: lcdtest_hear
1835	 *
1836	 * Description:
1837	 *   Continuous sound localization loop.
1838	 *   LCD + audio_init once at start.  Then loop up to 300 iterations:
1839	 *     capture N=2048 → onset gate → locate → eye_look → print.
1840	 *   Exits on iteration cap or serial keypress.
1841	 *
1842	 ****************************************************************************/
1843	
1844	#define HEAR_LOOP_MAX    80    /* ~4-5 s at ~60 ms per iteration */
1845	#define HEAR_N_SAMPLES   2048
1846	#define HEAR_ONSET_GATE  80   /* RMS threshold to trigger locate */
1847	
1848	static int lcdtest_hear(void)
1849	{
1850	  int tau_q8;
1851	  int dx;
1852	  int iter;
1853	  int n;
1854	  int energy;
1855	  int pin;
1856	  int count = 0;
1857	
1858	  /* ---- Hardware bring-up (same as lcdtest_go steps 1-5,7,9-10,12
1859	   *       but WITHOUT draw_eye — we paint emo eyes directly).
1860	   * ---- Step 1: GPIO 0-52 high, skip reserved pins ---- */
1861	
1862	  for (pin = 0; pin <= 52; pin++)
1863	    {
1864	      if (pin == 2 || pin == 3 || pin == 4 || pin == 5 ||
1865	          pin == 6 || pin == 7 || pin == 22 || pin == 23 ||
1866	          pin == 24 || pin == 25 || pin == 29)
1867	        {
1868	          continue;
1869	        }
1870	
1871	      if (pin == 10 || pin == 11 || pin == 8 ||
1872	          pin == 20 || pin == 21 ||
1873	          pin == 38 || pin == 39)
1874	        {
1875	          continue;
1876	        }
1877	
1878	      gpio_set_output(pin);
1879	      gpio_write(pin, 1);
1880	      count++;
1881	    }
1882	
1883	  /* Step 2: wait for power rails */
1884	
1885	  up_mdelay(500);
1886	
1887	  /* Step 3: backlight on */
1888	
1889	  gpio_set_output(LCD_PIN_BL);
1890	  gpio_write(LCD_PIN_BL, 1);
1891	
1892	  /* ---- Left eye: SPI pins + RST + init + display on ---- */
1893	
1894	  lcd_setup_pins(&g_lcd_left);
1895	  gpio_write(g_active_pins->rst, 0);
1896	  up_mdelay(15);
1897	  gpio_write(g_active_pins->rst, 1);
1898	  up_mdelay(120);
1899	  lcd_init_sequence(false);
1900	  lcd_display_on();
1901	
1902	  /* ---- Right eye: SPI pins + RST + init + display on ---- */
1903	
1904	  lcd_setup_pins(&g_lcd_right);
1905	  gpio_write(g_active_pins->rst, 0);
1906	  up_mdelay(15);
1907	  gpio_write(g_active_pins->rst, 1);
1908	  up_mdelay(120);
1909	  lcd_init_sequence(false);
1910	  lcd_display_on();
1911	
1912	  /* ---- Draw emo eyes (no round-eye flash) ---- */
1913	
1914	  lcd_set_pins(&g_lcd_left);
1915	  eye_neutral();
1916	  lcd_set_pins(&g_lcd_right);
1917	  eye_neutral();
1918	  lcd_set_pins(&g_lcd_left);
1919	
1920	  /* Initialize audio ADC (once) */
1921	
1922	  audio_init();
1923	
1924	  /* Suppress per-capture syslog during tight loop */
1925	
1926	  bk7258_mic_set_quiet(true);
1927	
1928	  syslog(LOG_INFO,
1929	         "[hear] === sound localization loop ===\n"
1930	         "[hear] loop_max=%d  N=%d  onset_gate=%d\n",
1931	         HEAR_LOOP_MAX, HEAR_N_SAMPLES, HEAR_ONSET_GATE);
1932	
1933	  for (iter = 0; iter < HEAR_LOOP_MAX; iter++)
1934	    {
1935	      /* Capture a chunk */
1936	
1937	      n = audio_capture(HEAR_N_SAMPLES);
1938	      if (n < 64)
1939	        {
1940	          continue;
1941	        }
1942	
1943	      /* Onset gate: check energy before running full locate */
1944	
1945	      energy = bk7258_mic_energy(n);
1946	      if (energy < HEAR_ONSET_GATE)
1947	        {
1948	          continue;
1949	        }
1950	
1951	      /* Sound detected — run full locate on this capture */
1952	
1953	      dx = mic_locate_process(n, &tau_q8);
1954	
1955	      syslog(LOG_INFO,
1956	             "[hear] iter=%d  energy=%d  dx=%d  "
1957	             "tau_q8=%d (%.2f samp)\n",
1958	             iter, energy, dx,
1959	             tau_q8, (double)tau_q8 / 256.0);
1960	
1961	      /* Drive eye toward detected direction (both panels) */
1962	
1963	      lcd_set_pins(&g_lcd_left);
1964	      eye_look(dx);
1965	      lcd_set_pins(&g_lcd_right);
1966	      eye_look(dx);
1967	      lcd_set_pins(&g_lcd_left);
1968	    }
1969	
1970	  /* Cleanup */
1971	
1972	  bk7258_mic_set_quiet(false);
1973	  audio_deinit();
1974	
1975	  syslog(LOG_INFO,
1976	         "[hear] loop ended after %d iterations\n", iter);
1977	
1978	  return OK;
1979	}
