2245	/****************************************************************************
2246	 * Name: bk7258_lcdtest_main
2247	 *
2248	 * Description:
2249	 *   NSH command "lcdtest":
2250	 *     lcdtest          — staged bring-up (A/B/C, diagnostics)
2251	 *     lcdtest go       — one-step dual-eye LCD bring-up
2252	 *     lcdtest anim     — pupil tracking animation (3 rounds)
2253	 *     lcdtest emo      — Cozmo/Vector expression eyes (2 rounds)
2254	 *     lcdtest oeye     — official-website-style eye preview
2255	 *     lcdtest blink [N] — smooth blink preview (default 5 blinks)
2256	 *     lcdtest hear     — sound localization → eye_look
2257	 *     lcdtest mic      — raw ADC capture + RMS dump
2258	 *     lcdtest pwr lo hi — power-on GPIO range for binary-search
2259	 *     lcdtest scan     — GPIO pin scan for LCD power enable
2260	 *
2261	 ****************************************************************************/
2262	
2263	int bk7258_lcdtest_main(int argc, char *argv[])
2264	{
2265	  if (argc > 1 && strcmp(argv[1], "go") == 0)
2266	    {
2267	      return lcdtest_go();
2268	    }
2269	
2270	  if (argc > 1 && strcmp(argv[1], "anim") == 0)
2271	    {
2272	      return lcdtest_anim();
2273	    }
2274	
2275	  if (argc > 1 && strcmp(argv[1], "emo") == 0)
2276	    {
2277	      return lcdtest_emo();
2278	    }
2279	
2280	  if (argc > 1 && strcmp(argv[1], "oeye") == 0)
2281	    {
2282	      return lcdtest_oeye();
2283	    }
2284	
2285	  if (argc > 1 && strcmp(argv[1], "blink") == 0)
2286	    {
2287	      int count = 5;
2288	
2289	      if (argc > 2)
2290	        {
2291	          count = atoi(argv[2]);
2292	        }
2293	
2294	      if (count < 1)
2295	        {
2296	          count = 1;
2297	        }
2298	
2299	      return lcdtest_blink(count);
2300	    }
2301	
2302	  if (argc > 1 && strcmp(argv[1], "scan") == 0)
2303	    {
2304	      return lcdtest_scan();
2305	    }
2306	
2307	  if (argc > 1 && strcmp(argv[1], "pwr") == 0)
2308	    {
2309	      int lo = 0;
2310	      int hi = 52;
2311	
2312	      if (argc > 2)
2313	        {
2314	          lo = atoi(argv[2]);
2315	        }
2316	
2317	      if (argc > 3)
2318	        {
2319	          hi = atoi(argv[3]);
2320	        }
2321	
2322	      if (lo < 0)
2323	        {
2324	          lo = 0;
2325	        }
2326	
2327	      if (hi > 52)
2328	        {
2329	          hi = 52;
2330	        }
2331	
2332	      if (lo > hi)
